// frontend/src/App.js
import React, { useState } from 'react';
import './App.css';

function App() {
  const [principal, setPrincipal] = useState('');
  const [term, setTerm] = useState('1');     // default to 1 year
  const [interestRate, setInterestRate] = useState('');
  const [frequency, setFrequency] = useState('Monthly');

  // For demo purposes, we’ll just display 0.00. 
  // You’d normally perform or fetch calculations here.
  const [finalAmount, setFinalAmount] = useState(0.0);
  const [totalInterest, setTotalInterest] = useState(0.0);
  const [effectiveRate, setEffectiveRate] = useState(0.0);

  const handleSubmit = (e) => {
    e.preventDefault();
    // TODO: Compute real GIC/compound interest 
    // or call your backend for the calculations.
    setFinalAmount(10000);      // Example placeholder
    setTotalInterest(500);      // Example placeholder
    setEffectiveRate(4.5);      // Example placeholder
  };

  return (
    <div className="app">
      {/* Header Section */}
      <header className="header">
        <h1>Calculate Your GIC Returns</h1>
        <p>
          Plan your secure investment with our GIC calculator. Get instant 
          calculations for your Guaranteed Investment Certificate returns 
          with current Canadian rates.
        </p>
      </header>

      {/* Main Calculator Container */}
      <main className="calculator-container">
        {/* Left Column: Calculator */}
        <section className="card left-card">
          <h2>GIC Calculator</h2>
          <form onSubmit={handleSubmit}>
            {/* Principal Amount */}
            <div className="form-group">
              <label htmlFor="principal">Principal Amount</label>
              <input
                id="principal"
                type="number"
                placeholder="$ 10000"
                value={principal}
                onChange={(e) => setPrincipal(e.target.value)}
                required
              />
            </div>

            {/* Term (Years) */}
            <div className="form-group">
              <label>Term (Years)</label>
              <div className="term-options">
                {['1Y','2Y','3Y','4Y','5Y'].map((label) => {
                  const yearVal = label.replace('Y', '');
                  return (
                    <label key={label} className="radio-label">
                      <input
                        type="radio"
                        name="term"
                        value={yearVal}
                        checked={term === yearVal}
                        onChange={() => setTerm(yearVal)}
                      />
                      {label}
                    </label>
                  );
                })}
              </div>
            </div>

            {/* Interest Rate (%) */}
            <div className="form-group">
              <label htmlFor="interestRate">Interest Rate (%)</label>
              <input
                id="interestRate"
                type="number"
                step="0.01"
                placeholder="4.5"
                value={interestRate}
                onChange={(e) => setInterestRate(e.target.value)}
                required
              />
            </div>

            {/* Compound Frequency */}
            <div className="form-group">
              <label htmlFor="frequency">Compound Frequency</label>
              <select
                id="frequency"
                value={frequency}
                onChange={(e) => setFrequency(e.target.value)}
              >
                <option value="Monthly">Monthly</option>
                <option value="Annually">Annually</option>
              </select>
            </div>

            {/* Calculate Button */}
            <button type="submit" className="calculate-btn">
              Calculate
            </button>
          </form>
        </section>

        {/* Right Column: Results */}
        <section className="card right-card">
          <h2>Results</h2>
          <div className="result-item">
            <span>Final Amount</span>
            <span>${finalAmount.toFixed(2)}</span>
          </div>
          <div className="result-item">
            <span>Total Interest Earned</span>
            <span>${totalInterest.toFixed(2)}</span>
          </div>
          <div className="result-item">
            <span>Effective Annual Rate</span>
            <span>{effectiveRate.toFixed(2)}%</span>
          </div>
        </section>
      </main>
    </div>
  );
}

export default App;
